SELECT      c.name AS career_name,     COUNT(DISTINCT x.job_offer_id) AS total_ofertas FROM careers c JOIN career_course cc ON cc.career_id = c.id JOIN courses co ON co.id = cc.course_id JOIN (     SELECT ct.course_id, tj.job_offer_id     FROM course_technology ct     JOIN technology_job tj ON tj.technology_id = ct.technology_id      UNION ALL      SELECT cl.course_id, lj.job_offer_id     FROM course_language cl     JOIN language_job lj ON lj.language_id = cl.language_id ) x ON x.course_id = co.id GROUP BY c.id, c.name ORDER BY total_ofertas DESC
